      const wpRes = await fetchWithTimeout2(`${origin}/wp-json/`, { headers: INSPECT_HEADERS }, 1e4);
      wpJson = wpRes.ok ? await readJsonIfPossible(wpRes) : null;
      const namespaces2 = Array.isArray(wpJson?.namespaces) ? wpJson.namespaces : [];
